update public.questions set body_hi = 'पशुओं और उन राज्यों के निम्नलिखित युग्मों पर विचार कीजिए जिनके वे राज्य पशु हैं:', explanation_hi = 'केवल तीन युग्म सही हैं। मिथुन अरुणाचल प्रदेश (और नागालैंड) का, धूमिल तेंदुआ (clouded leopard) मेघालय का, और हिम तेंदुआ हिमाचल प्रदेश का राज्य पशु है। लाल पांडा सिक्किम का राज्य पशु है; केरल का राज्य पशु भारतीय हाथी है।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. मिथुन", "2. धूमिल तेंदुआ", "3. हिम तेंदुआ", "4. लाल पांडा"], "list_2_hi": ["अरुणाचल प्रदेश", "मेघालय", "हिमाचल प्रदेश", "केरल"]}'::jsonb where id = 'b44a56f5-8368-4854-8878-adac18089ccc' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'मछलियों के प्रवास के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन I और II सही हैं। समुद्रापगामी (anadromous) मछलियाँ (हिल्सा, सैल्मन) समुद्र में बड़ी होती हैं और अंडे देने के लिए नदियों में आती हैं; नद्यपगामी (catadromous) मछलियाँ (मीठे पानी की ईल) इसका उलटा करती हैं। कथन III इसलिए सैल्मन के बारे में उलटी बात कहता है; सैल्मन तो समुद्रापगामी मछली का पाठ्यपुस्तकीय उदाहरण है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["हिल्सा समुद्रापगामी (anadromous) मछली है: यह समुद्र में रहती है और अंडे देने के लिए नदियों में ऊपर की ओर जाती है।", "मीठे पानी की ईल नद्यपगामी (catadromous) होती हैं: वे नदियों में रहती हैं और अंडे देने के लिए समुद्र में जाती हैं।", "सैल्मन नद्यपगामी मछलियाँ हैं।"]}'::jsonb where id = 'f9b59042-d633-4286-b620-dec3ac4e240c' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'समुद्री घोड़ों (seahorses) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। समुद्री घोड़ों में मादा नर की शिशु-थैली (brood pouch) में अंडे देती है, जहाँ वे निषेचित होते हैं और बच्चों के निकलने तक रखे जाते हैं। समुद्री घोड़े सिंगनैथिडी (Syngnathidae) कुल की अस्थिल मछलियाँ हैं (पाइपफ़िश के साथ)। पारंपरिक औषधि और एक्वेरियम के लिए भारी व्यापार के कारण 2004 से पूरे हिप्पोकैम्पस (Hippocampus) वंश को CITES के परिशिष्ट II में रखा गया है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["नर निषेचित अंडों को उनके फूटने तक अपनी शिशु-थैली में रखता है।", "समुद्री घोड़े मछलियाँ हैं।", "समुद्री घोड़ों की सभी प्रजातियाँ CITES के परिशिष्ट II में सूचीबद्ध हैं।"]}'::jsonb where id = 'd6843d68-074e-4c29-8504-f26540141755' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'हिम तेंदुए के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन I और II सही हैं। IUCN ने 2017 में हिम तेंदुए को संकटग्रस्त (Endangered) से सुभेद्य (Vulnerable) श्रेणी में रखा। भारत में इसका क्षेत्र लद्दाख से अरुणाचल प्रदेश तक ऊँचे हिमालय में फैला है। कथन III गलत है: जनवरी 2024 में जारी भारत में हिम तेंदुआ जनसंख्या आकलन (SPAI) ने 718 हिम तेंदुओं का अनुमान लगाया, जिनमें आधे से अधिक (477) लद्दाख में हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["IUCN रेड लिस्ट में इसे सुभेद्य (Vulnerable) श्रेणी में रखा गया है।", "भारत में इसका क्षेत्र लद्दाख, जम्मू-कश्मीर, हिमाचल प्रदेश, उत्तराखंड, सिक्किम और अरुणाचल प्रदेश के ऊँचे हिमालय में फैला है।", "2024 में जारी भारत के पहले हिम तेंदुआ जनसंख्या आकलन ने देश में 200 से कम हिम तेंदुओं का अनुमान लगाया।"]}'::jsonb where id = 'e2775fa3-d720-4dc5-840a-3844abde8174' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'भारत में गिद्धों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है। 1990 के दशक से भारत के जिप्स (Gyps) गिद्धों की संख्या में गिरावट का कारण डाइक्लोफ़ेनेक पाया गया, जो पशुओं को दी जाने वाली दर्द-निवारक दवा है: उपचारित पशुओं के शव खाने वाले गिद्धों के गुर्दे खराब हो जाते थे। DDT इसका कारण नहीं था। भारत ने 2006 में पशु-चिकित्सा में डाइक्लोफ़ेनेक पर रोक लगा दी, इसलिए कथन 3 भी गलत है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["गिद्ध मुर्दाखोर (scavenger) पक्षी हैं जो मुख्य रूप से शवों को खाते हैं।", "भारत के जिप्स गिद्धों की संख्या में भारी गिरावट मुख्य रूप से शवों में DDT के अवशेषों के कारण हुई।", "भारत में पशु-चिकित्सा में डाइक्लोफ़ेनेक का उपयोग अब भी अनुमत है।"]}'::jsonb where id = 'c562ab14-356b-424e-821e-b2e2f0a68391' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = '2010 में किस पशु को भारत का ''राष्ट्रीय विरासत पशु'' घोषित किया गया?', explanation_hi = 'हाथी कार्यबल (Elephant Task Force) की सिफ़ारिश पर 2010 में भारतीय हाथी को राष्ट्रीय विरासत पशु घोषित किया गया। बाघ राष्ट्रीय पशु बना हुआ है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "बाघ", "b": "हाथी", "c": "एशियाई शेर", "d": "गौर"}'::jsonb as hi) h) where id = 'eb660820-feff-4942-8742-3ece5653f3df' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'जम्मू और कश्मीर का राज्य पशु हंगुल (कश्मीरी हिरण) मुख्य रूप से किस संरक्षित क्षेत्र में बचा है?', explanation_hi = 'हंगुल की अंतिम टिकाऊ आबादी श्रीनगर के पास दाचीगाम राष्ट्रीय उद्यान पर केंद्रित है। हेमिस लद्दाख में है (हिम तेंदुए का क्षेत्र), ग्रेट हिमालयन राष्ट्रीय उद्यान हिमाचल प्रदेश में, और फूलों की घाटी उत्तराखंड में।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "हेमिस राष्ट्रीय उद्यान", "b": "ग्रेट हिमालयन राष्ट्रीय उद्यान", "c": "दाचीगाम राष्ट्रीय उद्यान", "d": "फूलों की घाटी राष्ट्रीय उद्यान"}'::jsonb as hi) h) where id = '81551224-f0c0-40ec-93b8-629ccf8a76d5' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित में से कौन-सा पक्षी कौओं के घोंसलों में अंडे देता है और अपने बच्चों को पालने का काम कौओं पर छोड़ देता है?', explanation_hi = 'एशियाई कोयल एक नीड़-परजीवी (brood parasite) है: मादा कौओं के घोंसलों में अंडे देती है और कौए उसके चूज़ों को पालते हैं। नीड़-परजीविता वह अंतःक्रिया है जिसमें एक प्रजाति दूसरी प्रजाति की माता-पिता वाली देखभाल का शोषण करती है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "एशियाई कोयल", "b": "घरेलू गौरैया", "c": "भारतीय रॉबिन (कलचुरी)", "d": "आम मैना"}'::jsonb as hi) h) where id = '16991697-f16a-4c4a-ab3f-b3f2d72b96d0' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'ऑलिव रिडले कछुए के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। ऑलिव रिडले बड़ी संख्या में एक साथ घोंसले बनाते हैं (''अरिबाडा''), और ओडिशा के गहिरमाथा, रुशिकुल्या और देवी नदी का मुहाना विश्व के ऐसे सबसे बड़े स्थलों में हैं। भारतीय जल के हर समुद्री कछुए की तरह ऑलिव रिडले वन्यजीव (संरक्षण) अधिनियम की अनुसूची I में है; IUCN इसे सुभेद्य (Vulnerable) मानता है। यह सबसे छोटे समुद्री कछुओं में से एक है; सबसे बड़ा लेदरबैक है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह ''अरिबाडा'' के लिए जाना जाता है, यानी एक साथ बड़े पैमाने पर घोंसले बनाना, जिसमें हज़ारों मादाएँ एक साथ तट पर आती हैं।", "ओडिशा में गहिरमाथा, रुशिकुल्या का मुहाना और देवी नदी का मुहाना इसके मुख्य सामूहिक घोंसला-स्थलों में हैं।", "यह वन्यजीव (संरक्षण) अधिनियम, 1972 की अनुसूची I में सूचीबद्ध है।"]}'::jsonb where id = 'dfd70c38-dc41-4bd1-86e1-b12072a86495' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'कृष्णमृग (blackbuck) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। कृष्णमृग खुले मैदानों और घास के मैदानों का मृग है। यह पंजाब का राज्य पशु है (हरियाणा और आंध्र प्रदेश का भी)। राजस्थान का बिश्नोई समुदाय कृष्णमृग और चिंकारा की रक्षा के लिए जाना जाता है। यह वन्यजीव (संरक्षण) अधिनियम की अनुसूची I में है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह खुले घास के मैदानों और झाड़ियों वाले क्षेत्रों का मृग है।", "यह पंजाब का राज्य पशु है।", "बिश्नोई समुदाय इसकी रक्षा के लिए जाना जाता है।"]}'::jsonb where id = '30364572-bedb-412c-be51-b085a822e56b' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'सोन चिरैया (Great Indian Bustard) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं। सोन चिरैया गंभीर रूप से संकटग्रस्त (Critically Endangered) है, और बचे हुए अधिकांश पक्षी राजस्थान के थार में हैं। सामने की ओर इसकी दृष्टि कमज़ोर होती है और यह नीचे तथा भारी उड़ान भरती है, इसलिए प्रायः ऊपर से जाने वाली बिजली की लाइनों से टकरा जाती है; भारतीय वन्यजीव संस्थान के अध्ययनों ने इन टक्करों को वयस्क पक्षियों की मौत का प्रमुख कारण बताया, इसीलिए इसके आवास में लाइनों को भूमिगत करने का आदेश दिया गया है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["IUCN रेड लिस्ट में इसे गंभीर रूप से संकटग्रस्त (Critically Endangered) श्रेणी में रखा गया है।", "थार में सोन चिरैया की मौत का एक प्रमुख कारण ऊपर से जाने वाली बिजली की लाइनों से टकराना है।"]}'::jsonb where id = 'c2e72f49-7924-474a-81a1-0406532b256e' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'हॉर्सशू केकड़ों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 और 3 सही हैं। हॉर्सशू केकड़े कीलिसेरेट (chelicerates) हैं, जिन्हें मकड़ियों और बिच्छुओं के साथ रखा जाता है। इनका रक्त लाल नहीं, नीला होता है: ऑक्सीजन ताँबा-आधारित प्रोटीन हीमोसायनिन ले जाता है। इनके रक्त से बना एमीबोसाइट लाइसेट इंजेक्शन वाली दवाओं और उपकरणों में जीवाणु एंडोटॉक्सिन की मानक जाँच है। भारत में ये केवल अंडमान और निकोबार द्वीपसमूह में नहीं, बल्कि पूर्वी तट पर, विशेषकर ओडिशा (बालासोर) और पश्चिम बंगाल में मिलते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["ये असली केकड़ों की तुलना में मकड़ियों और बिच्छुओं से अधिक निकट संबंधित हैं।", "इनका रक्त लाल होता है, क्योंकि यह हीमोग्लोबिन से ऑक्सीजन ले जाता है।", "इनके रक्त के एक अर्क का उपयोग टीकों और चिकित्सा उपकरणों में जीवाणु एंडोटॉक्सिन की जाँच के लिए होता है।", "भारत में ये केवल अंडमान और निकोबार द्वीपसमूह के आसपास मिलते हैं।"]}'::jsonb where id = '347b4645-59f3-4666-a758-b094a03423d0' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'स्लॉथ भालू (रीछ) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 3 सही हैं। स्लॉथ भालू कीट खाने में विशेषज्ञ है: इसके ऊपर के कृंतक दाँत नहीं होते, और यह उस खाली जगह तथा अपने लचीले होंठों से दीमक और चींटियों को उनके टीलों से चूस लेता है। मादाएँ बच्चों को पीठ पर ढोती हैं। कथन 2 गलत है: यह प्रजाति श्रीलंका और नेपाल में भी रहती है। IUCN इसे सुभेद्य (Vulnerable) मानता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह मुख्य रूप से दीमक और चींटियाँ खाता है, जिन्हें यह ऊपर के सामने वाले दाँतों के न होने से बनी खाली जगह से चूस लेता है।", "यह केवल भारत में पाया जाता है।", "मादाएँ अपने बच्चों को पीठ पर ढोती हैं।"]}'::jsonb where id = '14fa7b27-a456-450f-a18f-4a5d04e132e4' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं, किंतु कथन-II, कथन-I की व्याख्या नहीं करता। छोटे कान और थूथन ठंड में गर्मी का नुकसान घटाते हैं (एलन का नियम: ठंडी जलवायु के स्तनधारियों के शरीर के सिरे छोटे होते हैं)। मौसम के साथ फ़र का रंग बदलना, सर्दी में सफ़ेद और गर्मी में भूरा या धूसर, छलावरण (camouflage) है, जो एक अलग अनुकूलन है।', updated_at = now(), question_data = question_data || '{"assertion_hi": "आर्कटिक लोमड़ियों के कान और थूथन छोटे होते हैं।", "reason_hi": "आर्कटिक लोमड़ियाँ मौसम के साथ अपने फ़र का रंग बदलती हैं।"}'::jsonb where id = '371903c8-849a-4235-8d6a-80b595e8a1c3' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-I सही है: कुशल गुर्दों, बहुत सूखे मल और निर्जलीकरण सहने की क्षमता के कारण ऊँट लंबे समय तक बिना पानी पिए रह सकते हैं। कथन-II एक आम भ्रम है: कूबड़ में पानी नहीं, वसा जमा होती है।', updated_at = now(), question_data = question_data || '{"assertion_hi": "ऊँट लंबे समय तक बिना पानी पिए जीवित रह सकते हैं।", "reason_hi": "ऊँट अपने कूबड़ में पानी जमा करते हैं।"}'::jsonb where id = 'ce9efb17-d0fb-4f4e-a0a6-c346aea87038' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 3 सही हैं। ग्रीष्म-निष्क्रियता (aestivation) गर्मी और सूखे के प्रति गर्मियों की निष्क्रियता है; अफ़्रीकी लंगफ़िश इसका मानक उदाहरण है, जो अपना तालाब सूखने पर स्वयं को श्लेष्मा के कोश में बंद कर लेती है। कथन 2 गलत है: कई सरीसृप और उभयचर (मेंढक, कछुए, साँप) सर्दी निष्क्रिय अवस्था में बिताते हैं, इसलिए शीत-निष्क्रियता (hibernation) केवल स्तनधारियों तक सीमित नहीं है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["ग्रीष्म-निष्क्रियता (aestivation) निष्क्रियता की वह अवस्था है जिसमें कुछ जीव गर्म, शुष्क अवधि को झेलने के लिए चले जाते हैं।", "शीत-निष्क्रियता (hibernation) केवल स्तनधारियों में देखी जाती है; कोई सरीसृप या उभयचर शीत-निष्क्रिय नहीं होता।", "अफ़्रीकी लंगफ़िश अपना तालाब सूखने पर कीचड़ में श्लेष्मा के कोश के भीतर ग्रीष्म-निष्क्रियता में रहकर बचती है।"]}'::jsonb where id = '822c8b30-e855-4b10-bbc7-9d38c6c7aeb1' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं और कथन-II, कथन-I की व्याख्या करता है। पट्टीदार सिर वाले हंस (bar-headed geese) मध्य एशिया और भारत के बीच हिमालय पार करते हैं। इनका हीमोग्लोबिन ऑक्सीजन को अधिक मज़बूती से बाँधता है, जिससे वे बहुत पतली हवा वाली ऊँचाइयों पर भी पर्याप्त ऑक्सीजन ले पाते हैं।', updated_at = now(), question_data = question_data || '{"assertion_hi": "पट्टीदार सिर वाले हंस अपने प्रवास के दौरान हिमालय के ऊपर से उड़ सकते हैं।", "reason_hi": "पट्टीदार सिर वाले हंसों के हीमोग्लोबिन की ऑक्सीजन के प्रति बंधुता मैदानी हंसों से अधिक होती है, जिससे उन्हें पतली हवा में ऑक्सीजन लेने में मदद मिलती है।"}'::jsonb where id = '44a10c0b-399f-40b4-8bd3-70acc06f7fd6' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'भारत में संरक्षित किस पशु के ऊन से ''शहतूश'' शॉल बनाई जाती है?', explanation_hi = 'शहतूश तिब्बती मृग, यानी चिरू, के महीन भीतरी ऊन से बुना जाता है, जिसे पाने के लिए जानवर को मारना पड़ता है। चिरू तिब्बती पठार और लद्दाख के चांगथांग में रहता है; यह वन्यजीव (संरक्षण) अधिनियम की अनुसूची I और CITES के परिशिष्ट I में है, और शहतूश के व्यापार पर प्रतिबंध है।', updated_at = now() where id = '29c1f42a-a126-4516-961d-a2b6b9dce538' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'मैंग्रोव के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं। श्वसन-मूल (pneumatophores) हवा लेने के लिए कीचड़ से ऊपर उठती हैं, और जरायुजता (vivipary), यानी पैतृक पेड़ पर ही अंकुरण, पौधे को ज्वारीय कीचड़ में जल्दी जमने देती है। कथन 3 गलत है: भारत के पश्चिमी तट पर भी विस्तृत मैंग्रोव हैं, विशेषकर गुजरात की कच्छ की खाड़ी और खंभात की खाड़ी में (पश्चिम बंगाल के बाद गुजरात का मैंग्रोव क्षेत्र दूसरा सबसे बड़ा है), और महाराष्ट्र, गोवा, कर्नाटक तथा केरल के तटों पर।', updated_at = now(), question_data = question_data || '{"statements_hi": ["श्वसन-मूल (pneumatophores) वे हवाई जड़ें हैं जो जलभराव वाली, ऑक्सीजन-रहित कीचड़ में मैंग्रोव पौधों को ऑक्सीजन लेने में मदद करती हैं।", "जरायुज (viviparous) मैंग्रोव में बीज तब अंकुरित हो जाता है जब फल पैतृक पेड़ से जुड़ा ही होता है।", "भारत में मैंग्रोव केवल पूर्वी तट पर और अंडमान तथा निकोबार द्वीपसमूह में मिलते हैं।"]}'::jsonb where id = '098f1f7e-8ef5-4350-b1c4-dc30bb23e4e5' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'खेजड़ी वृक्ष (Prosopis cineraria) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। खेजड़ी राजस्थान का राज्य वृक्ष है (गुजरात का बरगद है)। यह थार का ही मूल वृक्ष है; अमेरिका से लाई गई प्रजाति एक अलग प्रोसोपिस, P. juliflora, है। 1730 का खेजड़ली बलिदान, जिसमें अमृता देवी और 360 से अधिक बिश्नोइयों ने प्राण दिए, खेजड़ी के वृक्षों को बचाने के लिए था।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह गुजरात का राज्य वृक्ष है।", "इसे मेक्सिको से थार मरुस्थल में लाया गया था।", "1730 में खेजड़ली में बिश्नोइयों का बलिदान साल वृक्षों को बचाने के लिए हुआ था।"]}'::jsonb where id = '24ede9d8-758b-4473-aa2f-c9ef7b056512' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'कीटभक्षी पौधों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं। कीटभक्षी पौधे नाइट्रोजन की कमी वाली मिट्टी और दलदलों में उगते हैं और नाइट्रोजन की कमी पूरी करने के लिए कीट पकड़ते हैं। भारत का एकमात्र देशी घटपर्णी (pitcher plant), Nepenthes khasiana, मेघालय का स्थानिक है। कथन 3 गलत है: वे हरे होते हैं और प्रकाश-संश्लेषण करते हैं; कीट पोषक तत्व देते हैं, मुख्य भोजन नहीं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["ये आम तौर पर नाइट्रोजन की कमी वाली मिट्टी में उगते हैं।", "घटपर्णी पौधा Nepenthes khasiana मेघालय का स्थानिक है।", "ये प्रकाश-संश्लेषण नहीं कर सकते और भोजन के लिए पूरी तरह कीटों पर निर्भर हैं।"]}'::jsonb where id = 'c0be6239-8219-4df4-9629-533f60565b4d' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2 सही है। पेड़ों पर उगने वाले अधिकांश ऑर्किड अधिपादप (epiphytes) होते हैं: वे पेड़ का उपयोग केवल सहारे के लिए करते हैं, अपना भोजन स्वयं बनाते हैं और नमी हवा से लेते हैं। इसके विपरीत, अमरबेल (Cuscuta) में पर्णहरित नहीं होता और यह चूषकांगों (haustoria) से पोषक पौधे का भोजन लेती है। अधिपादपों को परजीवी समझ लेना ही यहाँ का जाल है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["पेड़ों की डालियों पर उगने वाले ऑर्किड परजीवी हैं, जो पोषक पेड़ से अपना भोजन लेते हैं।", "अमरबेल (Cuscuta) एक परजीवी पौधा है जिसमें पर्णहरित नहीं होता और यह पोषक पौधे से अपना भोजन लेती है।"]}'::jsonb where id = '4f95e9b1-ec9c-4c50-b439-c02872d6d7f9' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-I गलत है, किंतु कथन-II सही है। वीनस फ़्लाईट्रैप (Dionaea muscipula) केवल अमेरिका के कैरोलिना तट के एक छोटे क्षेत्र का मूल निवासी है। यह कीटभक्षी है और कीटों पर अपनी पत्तियाँ बंद कर लेता है। भारत के देशी कीटभक्षी पौधों में Nepenthes, Drosera और Utricularia हैं।', updated_at = now(), question_data = question_data || '{"assertion_hi": "वीनस फ़्लाईट्रैप भारत के वनों का मूल निवासी है।", "reason_hi": "वीनस फ़्लाईट्रैप एक कीटभक्षी पौधा है।"}'::jsonb where id = '97cc836f-9c9f-4f4e-b571-d12354d513f8' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित में से कौन-सा एक फूलदार पौधा है जो उथले समुद्रों में पूरी तरह पानी में डूबा रहकर उगता है?', explanation_hi = 'समुद्री घास (seagrass) फूलदार पौधे (आवृतबीजी) हैं जो उथले तटीय जल में पूरी तरह डूबे रहते हैं, जैसे मन्नार की खाड़ी और पाक खाड़ी के वे मैदान जिनमें डुगोंग चरते हैं। केल्प, सरगासम और लाल शैवाल शैवाल हैं, फूलदार पौधे नहीं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "समुद्री घास", "b": "केल्प", "c": "सरगासम", "d": "लाल शैवाल"}'::jsonb as hi) h) where id = '89be4255-da1a-410c-b311-40a282d17ef3' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं और कथन-II, कथन-I की व्याख्या करता है। चट्टान पर प्राथमिक अनुक्रमण में अग्रणी प्रजाति के रूप में लाइकेन अम्ल छोड़ते हैं जो चट्टान को घोलकर मिट्टी बनना शुरू करते हैं, और मॉस तथा बाद के पौधों के लिए ज़मीन तैयार करते हैं।', updated_at = now(), question_data = question_data || '{"assertion_hi": "नंगी चट्टान पर बसने वाले सबसे पहले जीव प्रायः लाइकेन होते हैं।", "reason_hi": "लाइकेन ऐसे अम्ल छोड़ते हैं जो चट्टान को तोड़कर मिट्टी की शुरुआत करने में मदद करते हैं।"}'::jsonb where id = '2290fd66-5b7e-4d7b-b6cb-1fd79f3c389f' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 3 सही हैं। चंदन (Santalum album) एक अर्ध-परजीवी है: यह हरा होता है, पर इसकी जड़ें पोषक पौधों की जड़ों से जुड़ जाती हैं। साइकस नग्न बीज वाला एक अनावृतबीजी है, फूलदार पौधा नहीं; इसकी प्रवालाभ जड़ों (coralloid roots) में नाइट्रोजन-स्थिरीकरण करने वाले नील-हरित शैवाल रहते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["चंदन का पेड़ एक आंशिक मूल-परजीवी है जो दूसरे पौधों की जड़ों से पानी और खनिज लेता है।", "साइकस एक फूलदार पौधा (आवृतबीजी) है।", "साइकस की प्रवालाभ जड़ों में नाइट्रोजन-स्थिरीकरण करने वाले नील-हरित शैवाल (cyanobacteria) रहते हैं।"]}'::jsonb where id = 'bbcda73f-fc56-4326-8be1-285777615303' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'शुष्क क्षेत्रों के पौधों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं। मरुद्भिद (xerophytes) पानी बचाते हैं: मांसल तने पानी जमा करते हैं, पत्तियाँ काँटों में बदल जाती हैं और उपचर्म (cuticle) मोटा होता है। कथन 3 इसका उलटा बताता है: बहुत-से खुले रंध्रों वाली बड़ी, पतली पत्तियाँ पानी जल्दी गँवा देंगी।', updated_at = now(), question_data = question_data || '{"statements_hi": ["नागफनी (कैक्टस) अपने मांसल तनों में पानी जमा करती है।", "कई नागफनियों में पत्तियाँ काँटों में बदल जाती हैं, जिससे पानी का नुकसान घटता है।", "ऐसे पौधों में आम तौर पर वाष्पोत्सर्जन तेज़ करने के लिए बहुत-से खुले रंध्रों वाली बड़ी, पतली पत्तियाँ होती हैं।"]}'::jsonb where id = '2a1014b0-1e95-4551-aea5-e87ee66805d8' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'बाँस के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1, 2 और 3 सही हैं। बाँस घास कुल (Poaceae) का सदस्य है। कई प्रजातियाँ दशकों बाद एक साथ फूलती हैं और फिर मर जाती हैं; मिज़ोरम का ''मौतम'' Melocanna baccifera के लगभग 48 वर्ष के अंतर पर होने वाले फूलने के बाद आता है, जिसके बीज चूहों की संख्या में विस्फोट और अकाल का कारण बनते हैं। कथन 4 गलत है: नवंबर 2017 के भारतीय वन (संशोधन) अध्यादेश ने, जो बाद में अधिनियम बना, गैर-वन भूमि पर उगे बाँस को अधिनियम की ''वृक्ष'' की परिभाषा से हटा दिया, इसलिए इसे बिना परमिट काटा और ले जाया जा सकता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["बाँस एक घास है।", "बाँस की कुछ प्रजातियाँ लंबे अंतराल पर एक साथ फूलती हैं और फिर मर जाती हैं।", "मिज़ोरम का ''मौतम'' बाँस के फूलने से जुड़ा है, जिससे चूहों की संख्या में भारी वृद्धि होती है।", "वन क्षेत्र के बाहर उगाए गए बाँस को भी भारतीय वन अधिनियम, 1927 के तहत ''वृक्ष'' माना जाता है, इसलिए उसे काटने और ले जाने के लिए परमिट चाहिए।"]}'::jsonb where id = 'f0d07f07-3d55-4631-8bc1-5d6080e44b23' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'नीलकुरिंजी (Strobilanthes kunthiana) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। नीलकुरिंजी लगभग हर बारह वर्ष पर बड़े पैमाने पर खिलती है (मुन्नार के आसपास पिछली बड़ी बहार 2018 में थी) और पहाड़ी घास के मैदानों को नीला कर देती है। कई Strobilanthes की तरह यह एकफलनी (monocarpic) है: पौधे फूलने और बीज बनाने के बाद मर जाते हैं, और अगली पीढ़ी बीज से उगती है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह लगभग बारह वर्ष में एक बार फूलती है।", "यह दक्षिणी पश्चिमी घाट के शोला-घास के मैदान वाले भू-दृश्य में, विशेषकर मुन्नार के आसपास, उगती है।", "फूलने के बाद पौधे मर जाते हैं।"]}'::jsonb where id = '83a9efb6-251e-46d1-b0fe-cdc226c02975' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'राष्ट्रीय हरित अधिकरण (NGT) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 2 और 3 सही हैं। NGT 2010 में अपने ही अधिनियम के तहत बना, और इसकी प्रधान पीठ नई दिल्ली में है। कथन 1 गलत है: NGT उन कानूनों के मामलों का निर्णय करता है जो NGT अधिनियम की अनुसूची I में हैं, जैसे जल, वायु, पर्यावरण (संरक्षण), वन (संरक्षण) और जैव विविधता अधिनियम; वन्यजीव (संरक्षण) अधिनियम और भारतीय वन अधिनियम इनमें नहीं हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह वन्यजीव (संरक्षण) अधिनियम, 1972 से उत्पन्न मामलों की सुनवाई कर सकता है।", "इसकी स्थापना राष्ट्रीय हरित अधिकरण अधिनियम, 2010 के तहत हुई।", "इसकी प्रधान पीठ नई दिल्ली में बैठती है।"]}'::jsonb where id = '7d7c42d3-10be-44bd-a474-c2967c805dc6' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'राष्ट्रीय उद्यानों और वन्यजीव अभयारण्यों के आसपास पारिस्थितिक-संवेदनशील क्षेत्र (Eco-Sensitive Zones) केंद्र सरकार निम्नलिखित में से किस कानून के तहत अधिसूचित करती है?', explanation_hi = 'पारिस्थितिक-संवेदनशील क्षेत्र पर्यावरण, वन और जलवायु परिवर्तन मंत्रालय पर्यावरण (संरक्षण) अधिनियम, 1986 की धारा 3 और पर्यावरण (संरक्षण) नियम, 1986 के नियम 5 के तहत अधिसूचित करता है, जो केंद्र को किसी क्षेत्र में उद्योगों और प्रक्रियाओं पर रोक लगाने देते हैं। वन्यजीव (संरक्षण) अधिनियम स्वयं संरक्षित क्षेत्रों को नियंत्रित करता है, उनके आसपास के बफ़र को नहीं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "वन्यजीव (संरक्षण) अधिनियम, 1972", "b": "वन (संरक्षण) अधिनियम, 1980", "c": "जैव विविधता अधिनियम, 2002", "d": "पर्यावरण (संरक्षण) अधिनियम, 1986"}'::jsonb as hi) h) where id = '93153f0d-8b6b-4ecd-8d62-ad7050773e93' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'जैव विविधता अधिनियम, 2002 के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 3 सही हैं। राष्ट्रीय जैव विविधता प्राधिकरण चेन्नई में है, और जैव विविधता (संशोधन) अधिनियम, 2023 ने वैद्यों और हकीमों को मिली पुरानी छूट को उन पंजीकृत आयुष चिकित्सकों तक बढ़ाया जो जीविका के लिए चिकित्सा करते हैं। कथन 2 गलत है: यह अधिनियम जैव विविधता पर कन्वेंशन (CBD) को लागू करता है; रामसर कन्वेंशन आर्द्रभूमियों से संबंधित है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसके तहत स्थापित राष्ट्रीय जैव विविधता प्राधिकरण का मुख्यालय चेन्नई में है।", "इसे रामसर कन्वेंशन के तहत भारत के दायित्वों को लागू करने के लिए बनाया गया।", "2023 के संशोधन के बाद से, पंजीकृत आयुष चिकित्सकों को पेशे के रूप में देशी चिकित्सा करने में जैविक संसाधनों का उपयोग करने के लिए राज्य जैव विविधता बोर्ड को पूर्व सूचना देने की ज़रूरत नहीं है।"]}'::jsonb where id = '66a2b841-ffa6-4b54-af18-e30c2ec7234a' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'राष्ट्रीय बाघ संरक्षण प्राधिकरण (NTCA) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है। NTCA 2006 में उसी वर्ष के संशोधन से जोड़ी गई वन्यजीव (संरक्षण) अधिनियम की धारा 38L के तहत बना, और इसने प्रोजेक्ट टाइगर का स्थान लिया। इसकी अध्यक्षता प्रधानमंत्री नहीं, केंद्रीय पर्यावरण, वन और जलवायु परिवर्तन मंत्री करते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह वन्यजीव (संरक्षण) अधिनियम, 1972 के तहत गठित एक सांविधिक निकाय है।", "इसकी अध्यक्षता प्रधानमंत्री करते हैं।"]}'::jsonb where id = 'a7acfd87-fa0d-44d4-979c-a45cedde94ed' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'वन (संरक्षण) संशोधन अधिनियम, 2023 के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं। 1 दिसंबर 2023 से लागू इस संशोधन ने अधिनियम का नाम बदला और रणनीतिक रैखिक परियोजनाओं के लिए सीमा-क्षेत्र की छूट बनाई। कथन 3 उसके उलट है जो इसने किया: इसने संरक्षित क्षेत्रों के बाहर वन क्षेत्रों में सरकार या किसी प्राधिकरण के स्वामित्व वाले चिड़ियाघरों और सफ़ारी (वन्यजीव (संरक्षण) अधिनियम के तहत) को, इको-टूरिज़्म सुविधाओं और वन-वर्धन कार्यों के साथ, उन गतिविधियों में जोड़ा जिन्हें गैर-वन प्रयोजन नहीं माना जाता। (अलग से, फ़रवरी 2024 के उच्चतम न्यायालय के एक अंतरिम आदेश के अनुसार वन भूमि पर किसी नए चिड़ियाघर या सफ़ारी के लिए उसकी स्वीकृति आवश्यक है।)', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसने वन (संरक्षण) अधिनियम, 1980 का नाम बदलकर वन (संरक्षण एवं संवर्धन) अधिनियम, 1980 कर दिया।", "यह भारत की अंतरराष्ट्रीय सीमाओं, नियंत्रण रेखा या वास्तविक नियंत्रण रेखा के 100 किमी के भीतर की वन भूमि को, राष्ट्रीय महत्त्व और राष्ट्रीय सुरक्षा से जुड़ी रणनीतिक रैखिक परियोजनाओं के लिए आवश्यक होने पर, अधिनियम की स्वीकृति की शर्त से छूट देता है।", "यह संरक्षित क्षेत्रों के बाहर की वन भूमि पर चिड़ियाघरों और सफ़ारी पर रोक लगाता है।"]}'::jsonb where id = 'da6cd222-d892-411f-9788-60f86fc1a3d2' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
